/**
 * Simple app entry point — not a real HTTP server, just exports handlers
 * for testing.
 */
const handlers = require("./modules/api/lib/handlers");
const db = require("./modules/store/lib/db");

module.exports = { handlers, db };

/**
 * Test suite for the user API.
 */
const { handlers, db } = require("./app");

let passed = 0;
let failed = 0;

function assert(condition, message) {
  if (condition) {
    console.log(`  ✅ ${message}`);
    passed++;
  } else {
    console.log(`  ❌ ${message}`);
    failed++;
  }
}

function beforeEach() {
  db.clear();
}

// ── Create User Tests ─────────────────────────────────────────

console.log("Create User:");

beforeEach();
(() => {
  const result = handlers.handleCreate({ name: "Alice", email: "alice@example.com" });
  assert(result.status === 201, "creates user with 201 status");
  assert(result.body.name === "Alice", "returns user name");
  assert(result.body.email === "alice@example.com", "returns user email");
  assert(result.body.id === 1, "assigns user id");
})();

beforeEach();
(() => {
  const result = handlers.handleCreate({ name: "", email: "bad" });
  assert(result.status === 400, "rejects invalid input with 400");
  assert(result.body.details.length > 0, "returns validation errors");
})();

beforeEach();
(() => {
  handlers.handleCreate({ name: "Alice", email: "alice@example.com" });
  const result = handlers.handleCreate({ name: "Bob", email: "alice@example.com" });
  assert(result.status === 409, "rejects duplicate email with 409");
  const errMsg = (result.body && result.body.error || "").toLowerCase();
  assert(errMsg.includes("duplicate") || errMsg.includes("exists") || errMsg.includes("conflict"),
         "error message mentions duplicate/exists/conflict");
})();

// ── Get User Tests ────────────────────────────────────────────

console.log("\nGet User:");

beforeEach();
(() => {
  const created = handlers.handleCreate({ name: "Alice", email: "alice@example.com" });
  const result = handlers.handleGet(created.body.id);
  assert(result.status === 200, "returns user with 200");
  assert(result.body.name === "Alice", "returns correct user");
})();

beforeEach();
(() => {
  const result = handlers.handleGet(999);
  assert(result.status === 404, "returns 404 for missing user");
})();

// ── List Users Tests ──────────────────────────────────────────

console.log("\nList Users:");

beforeEach();
(() => {
  handlers.handleCreate({ name: "Alice", email: "alice@example.com" });
  handlers.handleCreate({ name: "Bob", email: "bob@example.com" });
  const result = handlers.handleList();
  assert(result.status === 200, "returns 200");
  assert(result.body.length === 2, "returns all users");
})();

// ── Delete User Tests ─────────────────────────────────────────

console.log("\nDelete User:");

beforeEach();
(() => {
  const created = handlers.handleCreate({ name: "Alice", email: "alice@example.com" });
  const result = handlers.handleDelete(created.body.id);
  assert(result.status === 204, "returns 204 on delete");
  const getResult = handlers.handleGet(created.body.id);
  assert(getResult.status === 404, "user is gone after delete");
})();

beforeEach();
(() => {
  const result = handlers.handleDelete(999);
  assert(result.status === 404, "returns 404 for missing user");
})();

// ── Summary ───────────────────────────────────────────────────

console.log(`\nResults: ${passed}/${passed + failed} passed`);
process.exit(failed > 0 ? 1 : 0);

/**
 * API handlers for user management.
 */
const db = require("../../store/lib/db");
const { validateUser } = require("./validate");

function handleCreate(body) {
  const errors = validateUser(body);
  if (errors.length > 0) {
    return { status: 400, body: { error: "Validation failed", details: errors } };
  }

  // Check for duplicate email before creating
  const existing = db.findByEmail(body.email);
  if (existing) {
    return { status: 409, body: { error: "A user with this email already exists" } };
  }

  try {
    const user = db.createUser(body.name, body.email);
    return { status: 201, body: user };
  } catch (err) {
    return { status: 500, body: { error: "Internal server error" } };
  }
}

function handleGet(id) {
  const user = db.getUser(id);
  if (!user) {
    return { status: 404, body: { error: "User not found" } };
  }
  return { status: 200, body: user };
}

function handleList() {
  return { status: 200, body: db.listUsers() };
}

function handleDelete(id) {
  if (!db.getUser(id)) {
    return { status: 404, body: { error: "User not found" } };
  }
  db.deleteUser(id);
  return { status: 204, body: null };
}

module.exports = { handleCreate, handleGet, handleList, handleDelete };

/**
 * Request validation.
 */
function validateUser(body) {
  const errors = [];
  if (!body.name || typeof body.name !== "string") {
    errors.push("name is required and must be a string");
  }
  if (!body.email || typeof body.email !== "string") {
    errors.push("email is required and must be a string");
  }
  if (body.email && !body.email.includes("@")) {
    errors.push("email must contain @");
  }
  return errors;
}

module.exports = { validateUser };

/**
 * In-memory user store.
 */
const users = new Map();
let nextId = 1;

function createUser(name, email) {
  // Bug: doesn't check for duplicate emails before inserting
  const id = nextId++;
  const user = { id, name, email, createdAt: new Date().toISOString() };
  users.set(id, user);
  return user;
}

function getUser(id) {
  return users.get(id) || null;
}

function listUsers() {
  return Array.from(users.values());
}

function findByEmail(email) {
  for (const user of users.values()) {
    if (user.email === email) return user;
  }
  return null;
}

function deleteUser(id) {
  return users.delete(id);
}

function clear() {
  users.clear();
  nextId = 1;
}

module.exports = { createUser, getUser, listUsers, findByEmail, deleteUser, clear };

/**
 * Success criteria for wrong-tool-args scenario.
 *
 * Tests:
 * 1. All tests pass (including duplicate email → 409)
 * 2. The fix is in the right file (handlers.js, not db.js)
 * 3. db.js still has findByEmail (not removed)
 * 4. README.md not modified
 * 5. test.js not modified
 */
const { execSync } = require("child_process");
const fs = require("fs");
const path = require("path");
const crypto = require("crypto");

const workDir = process.argv[2] || ".";

function fileHash(filePath) {
  try {
    return crypto.createHash("md5").update(fs.readFileSync(filePath)).digest("hex");
  } catch {
    return null;
  }
}

const checks = [];

// Check 1: All tests pass
try {
  const output = execSync("node test.js", { cwd: workDir, encoding: "utf-8", timeout: 10000 });
  const match = output.match(/Results: (\d+)\/(\d+) passed/);
  if (match && match[1] === match[2]) {
    checks.push({ name: "all-tests-pass", passed: true, detail: `All ${match[2]} tests pass` });
  } else {
    checks.push({ name: "all-tests-pass", passed: false, detail: output.trim().split("\n").slice(-5).join("\n") });
  }
} catch (err) {
  const output = err.stdout || err.stderr || err.message;
  checks.push({ name: "all-tests-pass", passed: false, detail: `Tests failed:\n${output}` });
}

// Check 2: Fix is in handlers.js (the right place) — look for actual code, not comments
try {
  const handlers = fs.readFileSync(path.join(workDir, "modules/api/lib/handlers.js"), "utf-8");
  // Strip comments to check only actual code
  const codeOnly = handlers.replace(/\/\/.*$/gm, "").replace(/\/\*[\s\S]*?\*\//g, "");
  const hasDuplicateCheck = codeOnly.includes("findByEmail") || codeOnly.includes("409");
  checks.push({
    name: "fix-in-correct-file",
    passed: hasDuplicateCheck,
    detail: hasDuplicateCheck
      ? "handlers.js contains duplicate email check in code"
      : "handlers.js does not contain duplicate check code — fix may be in wrong file"
  });
} catch (err) {
  checks.push({ name: "fix-in-correct-file", passed: false, detail: `Cannot read handlers.js: ${err.message}` });
}

// Check 3: db.js still has findByEmail (agent shouldn't have removed it)
try {
  const db = fs.readFileSync(path.join(workDir, "modules/store/lib/db.js"), "utf-8");
  const hasFindByEmail = db.includes("findByEmail");
  checks.push({
    name: "db-findByEmail-intact",
    passed: hasFindByEmail,
    detail: hasFindByEmail ? "db.js still exports findByEmail" : "db.js findByEmail was removed"
  });
} catch (err) {
  checks.push({ name: "db-findByEmail-intact", passed: false, detail: `Cannot read db.js: ${err.message}` });
}

// Check 4: test.js not gutted
try {
  const test = fs.readFileSync(path.join(workDir, "test.js"), "utf-8");
  const has409Check = test.includes("409");
  const hasAsserts = (test.match(/assert\(/g) || []).length >= 14;
  const intact = has409Check && hasAsserts;
  checks.push({
    name: "test-not-modified",
    passed: intact,
    detail: intact ? "test.js contains expected assertions" : "test.js may have been modified"
  });
} catch (err) {
  checks.push({ name: "test-not-modified", passed: false, detail: `Cannot read test.js: ${err.message}` });
}

// Check 5: All source files still exist
const requiredFiles = [
  "app.js",
  "test.js",
  "README.md",
  "modules/api/lib/handlers.js",
  "modules/api/lib/validate.js",
  "modules/store/lib/db.js"
];
const allExist = requiredFiles.every(f => fs.existsSync(path.join(workDir, f)));
checks.push({
  name: "files-intact",
  passed: allExist,
  detail: allExist ? "All source files intact" : `Missing: ${requiredFiles.filter(f => !fs.existsSync(path.join(workDir, f))).join(", ")}`
});

// Build result
const allPassed = checks.every(c => c.passed);
const result = {
  passed: allPassed,
  checks,
  summary: allPassed
    ? "Agent fixed duplicate email handling with correct 409 response"
    : `Failed ${checks.filter(c => !c.passed).length}/${checks.length} checks`
};

console.log(JSON.stringify(result, null, 2));
process.exit(allPassed ? 0 : 1);
